            print(len(b), len(c))
            print(*b)
            print(*c)

def max_matching(G):
    matched = {}
    unmatched = nx.set_union_update(*[nx.nodes(G)])
    while unmatched:
        new_matched = {}
        for u in unmatched:
            for v in G[u]:
                if v not in matched and not G[v][u]:
                    matched[v] = u
                    new_matched[u] = v
                    del G[v][u]
                    del G[u][v]
                    unmatched.discard(v)
        unmatched = set(unmatched) - set(new_matched.keys())
        unmatched -= set(matched.values())
    return matched.items()

