from sys import stdin, stdout

def solve():
    t = int(stdin.readline().strip())
    for _ in range(t):
        n, m = map(int, stdin.readline().strip().split())
        table = [[(i - 1) * m + j for j in range(1, m + 1)] for i in range(1, n + 1)]
        dp = [[float('inf')] * m for _ in range(n)]
        dp[0][0] = table[0][0]

        for i in range(1, n):
            for j in range(m):
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + table[i][j])
                if j + 1 < m:
                    dp[i][j + 1] = min(dp[i][j + 1], dp[i - 1][j] + table[i][j + 1])

        for j in range(1, m):
            for i in range(n - 1, -1, -1):
                dp[i][j] += min(dp[i + 1][j], dp[i][j - 1])

        stdout.write(f"{dp[-1][-1]\n}")

solve()
