import collections

def solve(n, m, adj, memo={}):
    key = (n, m)

    if key in memo:
        return memo[key]
    elif n == 1 and m == 1:
        return 0
    elif n == 1 or m == 1:
        return float('inf')
    else:
        cost = float('inf')
        for next_n, next_m in adj[(n, m)]:
            cost = min(cost, solve(next_n, next_m, adj, memo) + (n - 1) * m + next_m)
        memo[key] = cost

    return cost

def main():
