        n, m = map(int, stdin.readline().split())
        adj = collections.defaultdict(lambda: [])
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                adj[(i, j)].append((i + 1, j))
                if i < n:
                    adj[(i, j)].append((i, j + 1))
        cost = solve(n, m, adj)
        stdout.write(str(cost) + "\n")

